import java.io.*;
import java.util.*;

public class Main {
    static long MOD;

    static long add(long a, long b) {
        long result = a + b;
        if (result >= MOD) result -= MOD;
        return result;
    }

    static long multiply(long a, long b) {
        return (a * b) % MOD;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int n = fs.nextInt();
        int m = fs.nextInt();
        MOD = fs.nextLong();

        long[] inverse = new long[m + 1];
        inverse[1] = 1;
        for (int i = 2; i <= m; i++) {
            inverse[i] = MOD - multiply(MOD / i, inverse[(int) (MOD % i)]);
            if (inverse[i] == MOD) inverse[i] = 0;
        }

        long[] blockWays = new long[m + 1];
        long[] blockMadness = new long[m + 1];
        blockWays[0] = 1;

        for (int size = 1; size <= m; size++) {
            long waysSum = 0;
            long previousMadnessSum = 0;
            long lastMadnessSum = 0;

            for (int left = 0; left < size; left++) {
                int right = size - 1 - left;

                long productWays = multiply(blockWays[left], blockWays[right]);
                waysSum = add(waysSum, productWays);

                long previous = add(
                        multiply(blockMadness[left], blockWays[right]),
                        multiply(blockWays[left], blockMadness[right])
                );
                previousMadnessSum = add(previousMadnessSum, previous);

                long leftTriangular = (long) left * (left + 1) / 2;
                long rightTriangular = (long) right * (right + 1) / 2;
                long localMadness = (leftTriangular + rightTriangular) % MOD;

                lastMadnessSum = add(
                        lastMadnessSum,
                        multiply(localMadness, productWays)
                );
            }

            long factor = multiply(size + 1L, inverse[size]);
            blockWays[size] = multiply(factor, waysSum);

            blockMadness[size] = add(
                    multiply(factor, previousMadnessSum),
                    multiply(inverse[size], lastMadnessSum)
            );
        }

        long[][] ways = new long[m + 1][m + 1];
        long[][] madness = new long[m + 1][m + 1];
        ways[0][0] = 1;

        for (int blocks = 0; blocks < m; blocks++) {
            for (int used = blocks; used < m; used++) {
                long currentWays = ways[blocks][used];
                long currentMadness = madness[blocks][used];

                if (currentWays == 0 && currentMadness == 0) continue;

                for (int size = 1; used + size <= m; size++) {
                    int total = used + size;

                    ways[blocks + 1][total] = add(
                            ways[blocks + 1][total],
                            multiply(currentWays, blockWays[size])
                    );

                    long addedMadness = add(
                            multiply(currentMadness, blockWays[size]),
                            multiply(currentWays, blockMadness[size])
                    );

                    madness[blocks + 1][total] = add(
                            madness[blocks + 1][total],
                            addedMadness
                    );
                }
            }
        }

        int availableBlockPositions = n - m + 1;
        int maxBlocks = Math.min(m, availableBlockPositions);

        long answer = 0;
        long combination = 1;

        for (int blocks = 1; blocks <= maxBlocks; blocks++) {
            combination = multiply(combination, availableBlockPositions - blocks + 1L);
            combination = multiply(combination, inverse[blocks]);

            answer = add(
                    answer,
                    multiply(combination, madness[blocks][m])
            );
        }

        long factorial = 1;
        for (int i = 2; i <= m; i++) {
            factorial = multiply(factorial, i);
        }

        answer = multiply(answer, factorial);
        System.out.println(answer);
    }

    static class FastScanner {
        private final InputStream input;
        private final byte[] buffer = new byte[1 << 16];
        private int pointer = 0;
        private int length = 0;

        FastScanner(InputStream input) {
            this.input = input;
        }

        private int read() throws IOException {
            if (pointer >= length) {
                length = input.read(buffer);
                pointer = 0;
                if (length <= 0) return -1;
            }
            return buffer[pointer++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ');

            long value = 0;
            while (c > ' ') {
                value = value * 10 + (c - '0');
                c = read();
            }
            return value;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static int maxDegree;
    static long mod;

    static long multiplyMod(long a, long b) {
        return (a * b) % mod;
    }

    static long modPow(long base, long exponent) {
        long result = 1;
        while (exponent > 0) {
            if ((exponent & 1) != 0) {
                result = multiplyMod(result, base);
            }
            base = multiplyMod(base, base);
            exponent >>= 1;
        }
        return result;
    }

    static long[] multiplyPolynomials(long[] a, long[] b) {
        long[] result = new long[maxDegree + 1];

        for (int i = 0; i <= maxDegree; i++) {
            if (a[i] == 0) continue;
            int limit = maxDegree - i;

            for (int j = 0; j <= limit; j++) {
                if (b[j] == 0) continue;
                long value = result[i + j] + a[i] * b[j];
                result[i + j] = value % mod;
            }
        }

        return result;
    }

    static long[] polynomialPower(long[] base, int exponent) {
        long[] result = new long[maxDegree + 1];
        result[0] = 1;

        while (exponent > 0) {
            if ((exponent & 1) != 0) {
                result = multiplyPolynomials(result, base);
            }
            exponent >>= 1;
            if (exponent > 0) {
                base = multiplyPolynomials(base, base);
            }
        }

        return result;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int n = fs.nextInt();
        int m = fs.nextInt();
        mod = fs.nextLong();
        maxDegree = m;

        long[][] combination = new long[m + 1][m + 1];
        combination[0][0] = 1;
        for (int i = 1; i <= m; i++) {
            combination[i][0] = combination[i][i] = 1;
            for (int j = 1; j < i; j++) {
                combination[i][j] =
                        (combination[i - 1][j - 1] + combination[i - 1][j]) % mod;
            }
        }

        long[] fullCount = new long[m + 1];
        long[] fullMadness = new long[m + 1];
        fullCount[0] = 1;

        for (int k = 1; k <= m; k++) {
            long count = 0;
            long madness = 0;

            for (int left = 0; left < k; left++) {
                int right = k - 1 - left;
                long splitWays = combination[k - 1][left];

                long baseCount = multiplyMod(fullCount[left], fullCount[right]);

                long countTerm = multiplyMod(baseCount, k + 1L);
                count = (count + multiplyMod(splitWays, countTerm)) % mod;

                long previousMadness =
                        (multiplyMod(fullMadness[left], fullCount[right])
                                + multiplyMod(fullCount[left], fullMadness[right])) % mod;

                long lastChoicesPart = multiplyMod(k + 1L, previousMadness);

                long displacementSum =
                        ((long) left * (left + 1) / 2
                                + (long) right * (right + 1) / 2) % mod;

                long lastMadnessPart = multiplyMod(baseCount, displacementSum);
                long madnessTerm = (lastChoicesPart + lastMadnessPart) % mod;

                madness = (madness + multiplyMod(splitWays, madnessTerm)) % mod;
            }

            fullCount[k] = count;
            fullMadness[k] = madness;
        }

        long[] factorial = new long[m + 1];
        long[] inverseFactorial = new long[m + 1];
        factorial[0] = 1;

        for (int i = 1; i <= m; i++) {
            factorial[i] = multiplyMod(factorial[i - 1], i);
        }

        inverseFactorial[m] = modPow(factorial[m], mod - 2);
        for (int i = m; i >= 1; i--) {
            inverseFactorial[i - 1] = multiplyMod(inverseFactorial[i], i);
        }

        long[] basePolynomial = new long[m + 1];
        long[] madnessPolynomial = new long[m + 1];
        basePolynomial[0] = 1;

        for (int k = 1; k <= m; k++) {
            basePolynomial[k] = multiplyMod(fullCount[k], inverseFactorial[k]);
            madnessPolynomial[k] = multiplyMod(fullMadness[k], inverseFactorial[k]);
        }

        int emptySlotsParameter = n - m + 1;
        long[] poweredBase = polynomialPower(basePolynomial, emptySlotsParameter - 1);

        long coefficient = 0;
        for (int k = 1; k <= m; k++) {
            coefficient =
                    (coefficient
                            + multiplyMod(madnessPolynomial[k], poweredBase[m - k])) % mod;
        }

        long answer = multiplyMod(coefficient, emptySlotsParameter);
        answer = multiplyMod(answer, factorial[m]);

        System.out.println(answer);
    }

    static class FastScanner {
        private final InputStream input;
        private final byte[] buffer = new byte[1 << 16];
        private int pointer = 0;
        private int length = 0;

        FastScanner(InputStream input) {
            this.input = input;
        }

        private int read() throws IOException {
            if (pointer >= length) {
                length = input.read(buffer);
                pointer = 0;
                if (length <= 0) return -1;
            }
            return buffer[pointer++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ');

            long value = 0;
            while (c > ' ') {
                value = value * 10 + (c - '0');
                c = read();
            }
            return value;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }
}

