            fact[i] = mul(fact[i - 1], i);
        }

        invFact[m] = power(fact[m], mod - 2);
        for (int i = m; i >= 1; i--) {
            invFact[i - 1] = mul(invFact[i], i);
        }
        for (int i = 1; i <= m; i++) {
            inv[i] = mul(invFact[i], fact[i - 1]);
