        f[0] = 1;

        for (int s = 1; s <= m; s++) {
            long sum = 0;
            for (int i = 0; i < s; i++) {
                sum = add(sum, mul(f[i], f[s - 1 - i]));
            }
            f[s] = mul(mul(sum, s + 1L), inv[s]);
        }

