import java.io.*;
import java.util.*;

public class Main {
    private static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ');

            long value = 0;
            while (c > ' ') {
                value = value * 10 + (c - '0');
                c = read();
            }
            return value;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int n = (int) fs.nextLong();
        int m = (int) fs.nextLong();
        long mod = fs.nextLong();

        long[] inv = new long[n + 1];
        long[] fact = new long[n + 1];
        long[] invFact = new long[n + 1];

        fact[0] = 1;
        invFact[0] = 1;
        if (n >= 1) inv[1] = 1;

        for (int i = 1; i <= n; i++) {
            if (i >= 2) {
                inv[i] = (mod - (mod / i) * inv[(int) (mod % i)] % mod) % mod;
            }
            fact[i] = fact[i - 1] * i % mod;
            invFact[i] = invFact[i - 1] * inv[i] % mod;
        }

        long[] blockCount = new long[m + 1];
        long[] blockMadness = new long[m + 1];
        blockCount[0] = 1;

        for (int k = 1; k <= m; k++) {
            long count = 0;
            long madness = 0;
            long invK = inv[k];
            long countFactor = (k + 1L) * invK % mod;

            for (int left = 0; left < k; left++) {
                int right = k - 1 - left;

                long productCount =
                        blockCount[left] * blockCount[right] % mod;

                long addCount = productCount * countFactor % mod;
                count += addCount;
                if (count >= mod) count -= mod;

                long previousMadness =
                        blockMadness[left] * blockCount[right] % mod;
                previousMadness +=
                        blockCount[left] * blockMadness[right] % mod;
                if (previousMadness >= mod) previousMadness -= mod;

                long inside = previousMadness * (k + 1L) % mod;

                long displacement =
                        (long) left * (left + 1) / 2
                        + (long) right * (right + 1) / 2;
                inside += productCount * (displacement % mod) % mod;
                if (inside >= mod) inside -= mod;

                long addMadness = inside * invK % mod;
                madness += addMadness;
                if (madness >= mod) madness -= mod;
            }

            blockCount[k] = count;
            blockMadness[k] = madness;
        }

        int availableRuns = n - m + 1;
        int maxRuns = Math.min(m, availableRuns);

        long[] previousCount = new long[m + 1];
        long[] previousMadness = new long[m + 1];
        long[] currentCount = new long[m + 1];
        long[] currentMadness = new long[m + 1];

        previousCount[0] = 1;
        long answerNormalized = 0;

        for (int runs = 1; runs <= maxRuns; runs++) {
            Arrays.fill(currentCount, 0);
            Arrays.fill(currentMadness, 0);

            for (int used = runs - 1; used < m; used++) {
                long pc = previousCount[used];
                long pm = previousMadness[used];

                for (int size = 1; used + size <= m; size++) {
                    int total = used + size;

                    long addCount = pc * blockCount[size] % mod;
                    currentCount[total] += addCount;
                    if (currentCount[total] >= mod) {
                        currentCount[total] -= mod;
                    }

                    long addMadness =
                            pm * blockCount[size] % mod
                            + pc * blockMadness[size] % mod;
                    if (addMadness >= mod) addMadness -= mod;

                    currentMadness[total] += addMadness;
                    if (currentMadness[total] >= mod) {
                        currentMadness[total] -= mod;
                    }
                }
            }

            long placements = fact[availableRuns] * invFact[runs] % mod;
            placements = placements * invFact[availableRuns - runs] % mod;

            answerNormalized += placements * currentMadness[m] % mod;
            if (answerNormalized >= mod) answerNormalized -= mod;

            long[] temp = previousCount;
            previousCount = currentCount;
            currentCount = temp;

            temp = previousMadness;
            previousMadness = currentMadness;
            currentMadness = temp;
        }

        long answer = answerNormalized * fact[m] % mod;
        System.out.println(answer);
    }
}
